def build_model_overview(summaries, generated_at):
    date_str = generated_at.strftime("%B %d, %Y")
    time_str = generated_at.strftime("%H:%M UTC")

    def pct_color(v):
        return GREEN if float(v or 0) >= 0 else RED

    # Summary comparison table
